import java.io.*;
import java.util.*;

public class Main {
    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        int m = fs.nextInt();

        int[] type = new int[n];
        for (int i = 0; i < n; i++) {
            type[i] = fs.nextInt();
        }

        int[] head = new int[n];
        int[] reverseHead = new int[n];
        Arrays.fill(head, -1);
        Arrays.fill(reverseHead, -1);

        int[] to = new int[m];
        int[] next = new int[m];
        int[] reverseTo = new int[m];
        int[] reverseNext = new int[m];

        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;

            to[i] = b;
            next[i] = head[a];
            head[a] = i;

            reverseTo[i] = a;
            reverseNext[i] = reverseHead[b];
            reverseHead[b] = i;
        }

        boolean[] reachableFromAssignment = new boolean[n];
        boolean[] canReachUse = new boolean[n];
        int[] queue = new int[n];

        int front = 0;
        int back = 0;

        for (int i = 0; i < n; i++) {
            if (type[i] == 1) {
                reachableFromAssignment[i] = true;
                queue[back++] = i;
            }
        }

        while (front < back) {
            int current = queue[front++];

            for (int edge = head[current]; edge != -1; edge = next[edge]) {
                int destination = to[edge];

                if (type[destination] != 1 && !reachableFromAssignment[destination]) {
                    reachableFromAssignment[destination] = true;
                    queue[back++] = destination;
                }
            }
        }

        front = 0;
        back = 0;

        for (int i = 0; i < n; i++) {
            if (type[i] == 2) {
                canReachUse[i] = true;
                queue[back++] = i;
            }
        }

        while (front < back) {
            int current = queue[front++];

            for (int edge = reverseHead[current]; edge != -1; edge = reverseNext[edge]) {
                int predecessor = reverseTo[edge];

                if (!canReachUse[predecessor]) {
                    canReachUse[predecessor] = true;

                    if (type[predecessor] != 1) {
                        queue[back++] = predecessor;
                    }
                }
            }
        }

        StringBuilder result = new StringBuilder();
        for (int i = 0; i < n; i++) {
            result.append(reachableFromAssignment[i] && canReachUse[i] ? 1 : 0);
            result.append(i + 1 == n ? '\n' : ' ');
        }

        System.out.print(result);
    }
}

